<section class="page-heading"><div><p class="eyebrow">RAPPELS LIÉS À VOTRE ESPACE</p><h1>Notifications</h1><p class="subheading">Les rappels sont générés à partir de votre calendrier, votre linge et vos voyages.</p></div></section>
<?php if(!$notifications): ?><div class="empty-state"><h3>Vous êtes à jour</h3><p>Aucune notification pour le moment.</p></div><?php else: ?><div class="notification-list"><?php foreach($notifications as $notification): ?><article class="notification-card <?= $notification['read_at']?'read':'' ?>"><span class="notification-dot"></span><div><small><?= e(date('d.m.Y H:i',strtotime($notification['created_at']))) ?> · <?= e($notification['type']) ?></small><h2><?= e($notification['title']) ?></h2><p><?= e($notification['body']) ?></p></div><?php if(!$notification['read_at']): ?><form method="post" action="<?= e(url('notification-read')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($notification['id']) ?>"><button class="button secondary">Marquer comme lue</button></form><?php endif; ?></article><?php endforeach; ?></div><?php endif; ?>
